import type { LocalAiSetup, LocalAiState } from '@motivation/shared';

/** Story 427: how the chat server's two setups are named in the AI section and the home widget. */
export const LOCAL_AI_SETUP_LABELS: Record<LocalAiSetup, string> = {
    app: 'App (vision, 32k)',
    text: 'Text-only (84k)',
};

/**
 * Story 426: the one line both the AI section and the home widget show for the switch. A timed
 * hold past its `until` reads as off: the server released it then. Story 427: on, it names the setup.
 */
export function localAiLabel(state: LocalAiState, now: Temporal.Instant): string {
    const setup = state.setup ? ` · ${LOCAL_AI_SETUP_LABELS[state.setup]}` : '';
    if (state.mode === 'kept') return `Kept on${setup}`;
    if (state.mode === 'off' || state.until === null) return 'Off';
    const ms = Temporal.Instant.from(state.until).epochMilliseconds - now.epochMilliseconds;
    if (ms <= 0) return 'Off';
    return `On · ${Math.ceil(ms / 60_000)} min left${setup}`;
}
